/* Current four-loop milestone; prior round renderers remain available. */
(() => {
  'use strict';
  const prior=window.ResearchObservatory,D=window.ROUND23_DATA;
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const route=(id,label)=>`<a href="#research/${id}">${esc(label)}</a>`;
  const source=(path,label)=>`<a href="https://github.com/occult-kranti/yang_mills_workbench/blob/main/${esc(path)}">${esc(label)} ↗</a>`;
  const nav=()=>`<nav class="rc-nav" aria-label="Round23 research navigation">${route('home','Current results')}${route('round23-roadmap','Roadmap & handoff')}${route('round23-t2','T2 derivation')}${route('round22-home','Round22 archive')}${route('journey','Earlier research journey')}</nav>`;
  const status=x=>x.loop==='t2'?'Accepted within scope · single-agent self-review':x.status==='limited'?'Limited result':'Accepted within scope · prior independent-agent review';
  const links=x=>`<div class="r22-evidence">${source(`research/round23/contracts/${x.loop}.json`,'Frozen contract')}${source(`research/round23/forward/${x.loop}/report.md`,'Derivation')}${source(`research/round23/reverse/${x.loop}/report.md`,x.loop==='t2'?'Same-author obligation audit':'Reverse derivation')}${source(`research/round23/skeptic/${x.loop}.md`,x.loop==='t2'?'Critical self-review':'Skeptical review')}${source(`research/round23/advisor/${x.loop}-gate.json`,'Evidence gate')}</div>`;
  function card(x){return `<article class="rc-result"><p class="rc-kicker">${esc(x.loop.toUpperCase())} · ${esc(status(x))}</p><h2>${esc(x.claim)}</h2><p>${esc(x.scope)}</p>${route('round23-'+x.loop,'Read result, scope and evidence →')}</article>`;}
  function roadmap(){return `<header class="r22-page-head"><p class="rc-kicker">Stop after T2</p><h1>The next loop is planned, not started.</h1><p>Four of ten investigations are complete. U1 has no frozen contract, producer or gate. The user requested completion of the active loop only.</p></header><section class="rc-section"><h2>Next: U1 · actual canonical endpoint dynamics</h2><p>Freeze a bounded gauge-invariant fixed-support observable with nonzero variance. Study the canonical summable full-link family at T = C(ℏ/α)(1−q)⁻³, retaining fixed physical scales and controlled coupling to the remaining system.</p><p>This uses a different model from T2. Its ground-state gap and heat bounds cannot be transferred to the canonical endpoint question.</p><ol><li>U1: contract and execution remain pending.</li><li>U2: choose only after reviewing U1.</li><li>V and W: choose only after six reviewed S/T/U loops.</li></ol>${source('research/round23/HANDOFF.md','Full next handoff')}${links(D.loops[3])}</section><section class="r22-limit"><h2>Open research obligations</h2><ul>${D.roadmap.open_parent_goals.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>These remain open research questions after this PR is resolved.</p></section>`;}
  function home(){return `<section class="rc-hero"><div><p class="rc-kicker">Round23 · checkpoint through T2</p><h1>Ground-centered evolution, with an all-time error bound.</h1><p>The active loop is complete. The continuation stops here, with U1 left for the next handoff.</p><div class="rc-hero-actions">${route('round23-t2','Inspect the T2 result →')}${route('round23-roadmap','Next handoff →')}</div></div><aside class="rc-score"><span class="rc-score-number">4<span>/ 10</span></span><strong>Investigations completed</strong><p>Three accepted within scope · one limited</p><small>Counts research investigations, not the fraction of Yang–Mills solved.</small></aside></section><section class="r23-disclosure"><strong>T2 was completed by one agent.</strong><p>Its derivation, two formulations and critical self-review share one author. The earlier S1/S2/T1 independent-agent records are preserved. Scientific priority remains unverified; the four-dimensional continuum problem remains open.</p></section><section class="rc-section"><h2>What T2 adds</h2><div class="r22-hero-equation">sup<sub>t ≥ 0</sub> ‖S<sub>λ</sub>(t) − S̃<sub>λ</sub>(t)‖ ≤ <span>60λ²</span></div><p>Each heat evolution is centered using its own ground energy. For the specified finite physical graph, with all Hilbert-space sectors retained and 0 ≤ λ ≤ 0.01, the bound holds for every heat time. At λ = 0.01 its upper bound is 0.006. This is an absolute bound, not relative accuracy or a measured mass.</p></section><div class="rc-results rc-results-all">${D.loops.map(card).join('')}</div>`;}
  function loopPage(x){return `<header class="r22-page-head"><p class="rc-kicker">Round23 · ${esc(x.loop.toUpperCase())}</p><h1>${esc(x.claim)}</h1><p>${esc(status(x))}</p></header><section class="rc-section"><h2>Supported statement</h2>${x.equations.map(e=>`<div class="r22-formula">${esc(e)}</div>`).join('')}<p>${esc(x.scope)}</p><p>${esc(x.target_verdict)}</p>${x.loop==='t2'?'<p>The proof constructs isolated ground projections, bounds complementary leakage, and cancels the ground-ground term in centered Duhamel. Exact rational checks support the constants and failure controls; the written argument establishes the all-time statement.</p>':''}${links(x)}<h2>Review and limits</h2><p>${esc(x.next_missing_premise)}</p><ul>${x.limits.map(e=>`<li>${esc(e)}</li>`).join('')}</ul><details><summary>Authorship and verification</summary><pre>${esc(JSON.stringify(x.independence,null,2))}</pre></details><code class="r22-hash">Gate SHA-256: ${esc(x.gate_sha256)}</code><h2>Reproduce</h2><pre>python3 -B research/round23/reproduce.py --loops ${esc(x.loop)} --output /absolute/new/${esc(x.loop)}</pre><p>Scientific priority remains unverified. The continuum problem remains open.</p></section>`;}
  const owns=r=>['home','contributions','round23-roadmap'].includes(r)||D.loops.some(x=>r==='round23-'+x.loop);
  function render(r='home'){
    if(r==='round22-home')return `<div class="rc-history-notice">Round22 release archive. ${route('home','Current four-loop checkpoint →')}</div>`+prior.render('home');
    if(!owns(r))return (r==='journey'||r==='round22-roadmap'?`<div class="rc-history-notice">Historical Round22 record. Round23 is now at 4/10; U1 has not started. ${route('round23-roadmap','Current roadmap →')}</div>`:'')+prior.render(r);
    const content=r==='round23-roadmap'?roadmap():r==='home'||r==='contributions'?home():loopPage(D.loops.find(x=>r==='round23-'+x.loop));
    return `<div class="rc20 r21 r22 r23">${nav()}${content}<footer class="rc-footer"><strong>Yang–Mills Workbench · Round23</strong>${source('research/round23/HANDOFF.md','Handoff')}${route('round23-roadmap','Roadmap')}</footer></div>`;
  }
  function afterRender(){const r=location.hash.split('/')[1]||'home';if(owns(r)){window.ResearchJourney?.cleanup?.();document.title='Round23 · '+(r==='round23-roadmap'?'Next handoff':'Research checkpoint')+' · Yang–Mills Workbench';}else{prior.afterRender();}}
  window.ResearchRound23={render,afterRender,data:D};
  window.ResearchObservatory={...prior,render,afterRender};
})();
